<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in — MarketPG</title><script src="https://cdn.tailwindcss.com"></script></head><body class="grid min-h-screen place-items-center bg-gray-50 p-4"><main class="w-full max-w-md rounded-2xl border border-gray-200 bg-white p-7"><a href="/" class="text-xl font-medium text-gray-900">Market<span class="text-lime-600">PG</span></a><h1 class="mt-8 text-2xl font-medium text-gray-900">Welcome back</h1><p class="mt-2 text-sm text-gray-500">Sign in to continue shopping on MarketPG.</p><div id="error" class="mt-4 hidden rounded-lg bg-red-50 p-3 text-sm text-red-700"></div><form id="loginForm" class="mt-6 space-y-4"><div><label class="mb-1.5 block text-sm font-medium">Email address</label><input name="email" type="email" required autocomplete="email" class="w-full rounded-lg border border-gray-300 px-3 py-3 text-sm outline-none focus:border-lime-500"></div><div><label class="mb-1.5 block text-sm font-medium">Password</label><input name="password" type="password" required autocomplete="current-password" class="w-full rounded-lg border border-gray-300 px-3 py-3 text-sm outline-none focus:border-lime-500"></div><button id="submit" class="w-full rounded-lg bg-lime-400 px-4 py-3 text-sm font-semibold text-gray-950 hover:bg-lime-300">Sign in</button></form><p class="mt-5 text-center text-xs text-gray-400">New to MarketPG? Account registration is available in the mobile app.</p><a href="/" class="mt-5 block text-center text-sm text-gray-500 hover:text-gray-900">← Back to marketplace</a></main><script>document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();const btn=document.getElementById('submit'),err=document.getElementById('error');btn.disabled=true;btn.textContent='Signing in…';err.classList.add('hidden');try{const f=new FormData(e.target);const res=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({email:f.get('email'),password:f.get('password')})});const data=await res.json();if(!res.ok)throw new Error(data.message||'Unable to sign in.');sessionStorage.setItem('marketpg_token',data.token);sessionStorage.setItem('marketpg_user',JSON.stringify(data.user));location.href='/'}catch(ex){err.textContent=ex.message;err.classList.remove('hidden')}finally{btn.disabled=false;btn.textContent='Sign in'}})</script></body></html>